const input=$json.body??$json;
const arr=v=>Array.isArray(v)?v:[];
const truthy=v=>v===true||v==="true"||v===1||v==="1";
const requiredEvidence=arr(input.required_evidence);
const verifiedEvidence=arr(input.verified_evidence);
const milestones=arr(input.milestones);
const blockers=arr(input.blockers);
const identityComplete=Boolean(input.deal_id&&input.lead_id&&input.property_id);
const execution=input.execution??{};
const active=truthy(input.closing_active)||truthy(execution.active)||["active","in_progress","closing_active"].includes(String(execution.status||"").toLowerCase());
const verifiedIds=new Set(verifiedEvidence.map(e=>String(e.id??e)));
const evidenceComplete=requiredEvidence.length===0||requiredEvidence.every(e=>verifiedIds.has(String(e.id??e)));
const failedEvidence=verifiedEvidence.filter(e=>truthy(e.failed)||["failed","rejected","invalid"].includes(String(e.status||"").toLowerCase()));
const incompleteMilestones=milestones.filter(m=>!truthy(m.completed)&&!["completed","done","verified"].includes(String(m.status||"").toLowerCase()));
const overdueMilestones=milestones.filter(m=>truthy(m.overdue)||["overdue","failed"].includes(String(m.status||"").toLowerCase()));
const criticalOverdue=overdueMilestones.filter(m=>truthy(m.critical)||String(m.priority||"").toLowerCase()==="critical");
const blockersClear=blockers.length===0;
const recoveryNeeded=failedEvidence.length>0||criticalOverdue.length>0||truthy(input.recovery_required);
const reconciliationComplete=evidenceComplete&&failedEvidence.length===0&&incompleteMilestones.length===0&&blockersClear;

let status="evidence_reconciliation_required",nextWorkflow="WF-281",humanReview=false;
if(!identityComplete){status="blocked_missing_identity";nextWorkflow="WF-126";humanReview=true;}
else if(!active){status="closing_not_active";nextWorkflow="WF-279";humanReview=true;}
else if(!blockersClear){status="blocked";nextWorkflow="WF-126";humanReview=true;}
else if(recoveryNeeded){status="recovery_required";nextWorkflow="WF-282";humanReview=true;}
else if(reconciliationComplete){status="evidence_reconciled";nextWorkflow="WF-282";}
else if(!evidenceComplete||incompleteMilestones.length>0){status="evidence_gap";nextWorkflow="WF-282";humanReview=true;}

return [{json:{...input,workflow:"WF-281",workflow_name:"Milestone Update → Closing Evidence Reconciliation & Recovery Routing Controller",status,evidence_reconciliation:{identity_complete:identityComplete,closing_active:active,required_evidence_count:requiredEvidence.length,verified_evidence_count:verifiedEvidence.length,evidence_complete:evidenceComplete,failed_evidence_count:failedEvidence.length,incomplete_milestone_count:incompleteMilestones.length,overdue_milestone_count:overdueMilestones.length,critical_overdue_count:criticalOverdue.length,blockers_clear:blockersClear,recovery_needed:recoveryNeeded,reconciled:reconciliationComplete},next_workflow:nextWorkflow,human_review_required:humanReview,routing_reason:status,audit:{event_type:"closing_evidence_reconciliation_recovery_routing",idempotency_key:input.idempotency_key||`wf-281:${input.deal_id||"unknown"}:${input.evidence_reconciliation_id||"none"}:${input.version||1}`}}}];
